/* Smart Student Report System
   Front-end academic demo using browser Local Storage.
   For real deployment, replace this with a secure backend/database. */
const DB_KEY="srs_database_v2", SESSION_KEY="srs_session_v2";
const $=id=>document.getElementById(id);
const readDB=()=>JSON.parse(localStorage.getItem(DB_KEY)||"null");
const writeDB=db=>localStorage.setItem(DB_KEY,JSON.stringify(db));
const session=()=>JSON.parse(localStorage.getItem(SESSION_KEY)||"null");
const setSession=u=>localStorage.setItem(SESSION_KEY,JSON.stringify({username:u.username,role:u.role,studentId:u.studentId||null}));
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function initialDB(){let db=readDB();if(db)return db;db={users:[{name:"System Admin",username:"admin",password:"admin123",role:"admin",status:"active"}],students:[]};writeDB(db);return db}
function grade(mark){if(mark>=90)return"A+";if(mark>=80)return"A";if(mark>=70)return"B";if(mark>=60)return"C";if(mark>=50)return"D";return"F"}
function studentAverage(s){let a=(s.subjects||[]).map(x=>Number(x.internal||0)+Number(x.external||0));return a.length?(a.reduce((x,y)=>x+y,0)/a.length).toFixed(1):"0.0"}
function getUser(){let ss=session();if(!ss)return null;return readDB().users.find(u=>u.username===ss.username&&u.role===ss.role)||null}
function linkedStudent(u){let db=readDB();let id=u.role==="student"?u.studentId:u.role==="parent"?u.linkedStudentId:null;return db.students.find(s=>s.id===id)||null}
function pageGuard(){let role=document.body.dataset.rolePage;if(role){let u=getUser();if(!u||u.status!=="active"||u.role!==role){location.href="login.html";return null}$("welcome")&&($("welcome").textContent=`Welcome, ${u.name} (${u.username})`);return u}if(document.body.dataset.protected){let u=getUser();if(!u||u.status!=="active"){location.href="login.html";return null}if(u.role==="parent"&&!linkedStudent(u)){alert("No linked student record was found. Contact the administrator.");location.href="login.html";return null}return u}return getUser()}
function logout(){localStorage.removeItem(SESSION_KEY);location.href="login.html"}
window.initSRS=()=>{initialDB();const out=$("logoutBtn");if(out)out.addEventListener("click",e=>{e.preventDefault();logout()});const dl=$("dashboardLink");if(dl){let u=getUser();dl.href=u?({admin:"admin-dashboard.html",teacher:"teacher-dashboard.html",student:"student-dashboard.html",parent:"parent-dashboard.html"}[u.role]):"login.html"}setupLogin();const role=document.body.dataset.rolePage;if(role){let u=pageGuard();if(u){if(role==="admin")adminPage();if(role==="teacher")teacherPage();if(role==="student")studentPage();if(role==="parent")parentPage()}}if(document.body.dataset.protected){let u=pageGuard();if(u){if(location.pathname.endsWith("report.html")){reportPage(u);if(u.role==="teacher")reportPageInitButtons()}if(location.pathname.endsWith("analytics.html"))analyticsPage(u)}}};
function setupLogin(){let form=$("loginForm");if(!form)return;const role=$("loginRole"),parentWrap=$("parentStudentField");role.addEventListener("change",()=>parentWrap.classList.toggle("hidden",role.value!=="parent"));
let signupToggle=$("showSignup"),signupPanel=$("signupPanel"),signupForm=$("signupForm");if(signupToggle&&signupPanel)signupToggle.onclick=()=>signupPanel.classList.toggle("hidden");let signupRole=$("signupRole");if(signupRole)signupRole.onchange=()=>{$("signupStudentFields").classList.toggle("hidden",signupRole.value!=="student");$("signupParentFields").classList.toggle("hidden",signupRole.value!=="parent");$("signupStudentId").required=signupRole.value==="student";$("signupLinkedId").required=signupRole.value==="parent";};if(signupRole)signupRole.onchange();
form.addEventListener("submit",e=>{e.preventDefault();let db=readDB(),r=role.value,username=$("loginUsername").value.trim(),password=$("loginPassword").value,u=db.users.find(x=>x.role===r&&x.username.toLowerCase()===username.toLowerCase()&&x.password===password);if(!u){$("loginMessage").textContent="Invalid role, username or password.";return}if(u.status!=="active"){$("loginMessage").textContent="This account is inactive. Contact the administrator.";return}if(r==="parent"){let sid=$("parentStudentId").value.trim();if(!sid||sid!==u.linkedStudentId||!db.students.some(s=>s.id===sid)){$("loginMessage").textContent="Enter the correct linked student's university ID.";return}}if(r==="student"&&!db.students.some(s=>s.id===u.studentId)){$("loginMessage").textContent="Student profile is missing. Contact the administrator.";return}setSession(u);location.href=({admin:"admin-dashboard.html",teacher:"teacher-dashboard.html",student:"student-dashboard.html",parent:"parent-dashboard.html"})[r]});
if(signupForm)signupForm.addEventListener("submit",e=>{e.preventDefault();let d=readDB(),r=$("signupRole").value,name=$("signupName").value.trim(),username=$("signupUsername").value.trim(),password=$("signupPassword").value;if(d.users.some(x=>x.username.toLowerCase()===username.toLowerCase())){$("signupMessage").textContent="Username already exists.";return}let u={name,username,password,role:r,status:"active",email:$("signupEmail").value.trim()};if(r==="student"){let id=$("signupStudentId").value.trim();if(!id||d.students.some(s=>s.id===id)){$("signupMessage").textContent="Enter a unique university ID.";return}let student={id,name,department:$("signupDepartment").value.trim(),branch:$("signupBranch").value.trim(),year:$("signupYear").value.trim(),email:u.email,parentId:"",phone:"",parentPhone:"",cgpa:0,attendance:0,remarks:"No teacher remarks yet.",subjects:[]};d.students.push(student);u.studentId=id}else{let id=$("signupLinkedId").value.trim();if(!d.students.some(s=>s.id===id)){$("signupMessage").textContent="Enter an existing student university ID.";return}if(d.users.some(x=>x.role==="parent"&&x.linkedStudentId===id)){$("signupMessage").textContent="A parent account already exists for this student.";return}u.linkedStudentId=id}d.users.push(u);writeDB(d);$("signupMessage").textContent="Account created. You can now log in.";signupForm.reset();});}

function adminPage(){let db=readDB(),users=db.users.filter(u=>u.role!=="admin");$("countStudents").textContent=db.students.length;$("countTeachers").textContent=users.filter(u=>u.role==="teacher").length;$("countParents").textContent=users.filter(u=>u.role==="parent").length;$("countInactive").textContent=users.filter(u=>u.status==="inactive").length;let body=$("membersBody");body.innerHTML=users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${esc(u.studentId||u.teacherUniversityId||u.linkedStudentId||"—")}</td><td>${u.role==="teacher"?esc((u.teachingSubjects||[]).join(", ")||"Not assigned"):"—"}</td><td class="status ${u.status}">${u.status}</td><td><button class="btn ${u.status==="active"?"orange":"green"}" data-toggle="${esc(u.username)}">${u.status==="active"?"Deactivate":"Activate"}</button> <button class="btn orange" data-delete="${esc(u.username)}">Remove</button></td></tr>`).join("")||'<tr><td colspan="7">No members added yet.</td></tr>';body.querySelectorAll("[data-toggle]").forEach(b=>b.onclick=()=>{let d=readDB(),x=d.users.find(u=>u.username===b.dataset.toggle);x.status=x.status==="active"?"inactive":"active";writeDB(d);adminPage()});body.querySelectorAll("[data-delete]").forEach(b=>b.onclick=()=>{if(!confirm("Remove this account?"))return;let d=readDB(),x=d.users.find(u=>u.username===b.dataset.delete);if(x.role==="student")d.students=d.students.filter(s=>s.id!==x.studentId);d.users=d.users.filter(u=>u.username!==x.username);writeDB(d);adminPage()});$("studentDirectory").innerHTML=db.students.map(s=>`<tr><td>${esc(s.id)}</td><td>${esc(s.name)}</td><td>${esc(s.department)}</td><td>${esc(s.branch)}</td><td>${esc(s.year)}</td><td>${esc(s.email)}</td></tr>`).join("")||'<tr><td colspan="6">No student records yet.</td></tr>';let role=$("memberRole");role.onchange=()=>toggleMemberFields();toggleMemberFields();$("memberForm").onsubmit=addMember}
function toggleMemberFields(){let r=$("memberRole").value;["studentIdWrap","departmentWrap","branchWrap","yearWrap","parentIdWrap","parentPhoneWrap"].forEach(id=>$(id).classList.toggle("hidden",r!=="student"));$("linkedStudentWrap").classList.toggle("hidden",r!=="parent");$("teacherIdWrap").classList.toggle("hidden",r!=="teacher");$("teacherSubjectsWrap").classList.toggle("hidden",r!=="teacher");$("mTeacherId").required=r==="teacher"}
function addMember(e){e.preventDefault();let d=readDB(),r=$("memberRole").value,username=$("mUsername").value.trim();if(d.users.some(u=>u.username.toLowerCase()===username.toLowerCase()))return $("memberMessage").textContent="Username already exists.";let u={name:$("mName").value.trim(),username,password:$("mPassword").value,role:r,status:$("mStatus").value,email:$("mEmail").value.trim(),phone:$("mPhone").value.trim()};if(r==="student"){let id=$("mStudentId").value.trim();if(!id)return $("memberMessage").textContent="Enter the university ID manually.";if(d.students.some(s=>s.id===id))return $("memberMessage").textContent="That university ID already exists.";let s={id,name:u.name,department:$("mDepartment").value.trim(),branch:$("mBranch").value.trim(),year:$("mYear").value.trim(),email:u.email,parentId:$("mParentId").value.trim(),phone:u.phone,parentPhone:$("mParentPhone").value.trim(),cgpa:0,attendance:0,remarks:"No teacher remarks yet.",subjects:[]};d.students.push(s);u.studentId=id}else if(r==="teacher"){let id=$("mTeacherId").value.trim();if(!id)return $("memberMessage").textContent="Enter the teacher university ID manually.";if(d.users.some(x=>x.role==="teacher"&&x.teacherUniversityId===id))return $("memberMessage").textContent="That teacher university ID already exists.";u.teacherUniversityId=id;let subjects=$("mTeacherSubjects").value.split(",").map(x=>x.trim()).filter(Boolean);u.teachingSubjects=[...new Map(subjects.map(x=>[x.toLowerCase(),x])).values()];if(!u.teachingSubjects.length)return $("memberMessage").textContent="Enter at least one subject taught by this teacher."}else if(r==="parent"){let id=$("mLinkedStudent").value.trim();if(!d.students.some(s=>s.id===id))return $("memberMessage").textContent="Linked student ID does not exist. Add the student first.";if(d.users.some(x=>x.role==="parent"&&x.linkedStudentId===id))return $("memberMessage").textContent="A parent account is already linked to this student.";u.linkedStudentId=id;u.parentId=$("mParentId").value.trim()}d.users.push(u);writeDB(d);$("memberMessage").textContent="Member added successfully."; $("memberMessage").style.color="#059669";$("memberForm").reset();toggleMemberFields();adminPage()}
function teacherPage(){let db=readDB(),students=db.students,teacher=getUser();let assigned=teacher.teachingSubjects||[];let subjectBox=$("teacherSubjectsList");if(subjectBox)subjectBox.innerHTML=assigned.length?assigned.map(x=>`<span class="badge">${esc(x)}</span>`).join(" "):'<span class="muted">No subjects assigned yet. Contact the administrator.</span>';$("teacherStudentCount").textContent=students.length;let av=students.map(studentAverage),at=students.map(s=>Number(s.attendance||0));$("teacherAverage").textContent=av.length?(av.reduce((a,b)=>a+Number(b),0)/av.length).toFixed(1)+"%":"—";$("teacherAttendance").textContent=at.length?(at.reduce((a,b)=>a+b,0)/at.length).toFixed(1)+"%":"—";$("teacherStudents").innerHTML=students.map(s=>`<tr><td>${esc(s.id)}</td><td>${esc(s.name)}</td><td>${esc(s.branch)}</td><td>${studentAverage(s)}%</td><td>${s.attendance||0}%</td><td><a class="btn primary" href="report.html?student=${encodeURIComponent(s.id)}">Manage report</a></td></tr>`).join("")||'<tr><td colspan="6">No students have been added by the admin.</td></tr>'}
function profileHTML(s){return [["University ID",s.id],["Name",s.name],["Department",s.department],["Branch",s.branch],["Academic year",s.year],["Email",s.email],["Parent ID",s.parentId],["Phone",s.phone],["Parent phone",s.parentPhone],["CGPA",s.cgpa]].map(([k,v])=>`<div><b>${esc(k)}</b><strong>${esc(v||"—")}</strong></div>`).join("")}
function studentPage(){let s=linkedStudent(getUser());if(!s)return;$("studentProfile").innerHTML=profileHTML(s);$("studentAverage").textContent=studentAverage(s)+"%";$("studentAttendance").textContent=(s.attendance||0)+"%";$("studentCgpa").textContent=Number(s.cgpa||0).toFixed(2);let body=$("studentSubjectsBody");if(body){body.innerHTML=(s.subjects||[]).map(x=>{let internal=Number(x.internal||0),external=Number(x.external||0),total=internal+external;return `<tr><td>${esc(x.name)}</td><td>${internal}/30</td><td>${external}/70</td><td>${total}/100</td><td>${grade(total)}</td></tr>`}).join("")||'<tr><td colspan="5">No subjects have been added by your teacher yet.</td></tr>'}}
function parentPage(){let s=linkedStudent(getUser());if(!s)return;$("parentStudentProfile").innerHTML=profileHTML(s);$("parentAverage").textContent=studentAverage(s)+"%";$("parentAttendance").textContent=(s.attendance||0)+"%";$("parentCgpa").textContent=Number(s.cgpa||0).toFixed(2)}
function canSeeStudent(u,s){if(u.role==="admin"||u.role==="teacher")return true;if(u.role==="student")return u.studentId===s.id;if(u.role==="parent")return u.linkedStudentId===s.id;return false}
function selectedStudent(u){let db=readDB(),id=new URLSearchParams(location.search).get("student");if(u.role==="student")id=u.studentId;if(u.role==="parent")id=u.linkedStudentId;if(!id&&db.students.length)id=db.students[0].id;return db.students.find(s=>s.id===id&&canSeeStudent(u,s))}
function reportPage(u){
 let db=readDB(),wrap=$("studentPickerWrap"),picker=$("studentPicker");
 if(u.role==="teacher"||u.role==="admin"){
  wrap.classList.remove("hidden");
  picker.innerHTML=db.students.map(s=>`<option value="${esc(s.id)}">${esc(s.id)} — ${esc(s.name)}</option>`).join("");
  let q=new URLSearchParams(location.search).get("student");
  if(q){picker.value=q;$("studentIdSearch").value=q;}
  picker.onchange=()=>{let id=picker.value;$("studentIdSearch").value=id;history.replaceState(null,"","report.html?student="+encodeURIComponent(id));$("studentLookupMessage").textContent="";renderReport(u);};
  const find=()=>{let id=$("studentIdSearch").value.trim(),student=readDB().students.find(s=>s.id===id);
   if(!id){$("studentLookupMessage").style.color="#dc2626";$("studentLookupMessage").textContent="Please enter a university ID.";return;}
   if(!student){$("studentLookupMessage").style.color="#dc2626";$("studentLookupMessage").textContent="No student found with this university ID.";return;}
   picker.value=id;history.replaceState(null,"","report.html?student="+encodeURIComponent(id));$("studentLookupMessage").style.color="#059669";$("studentLookupMessage").textContent="Student report opened.";renderReport(u);
  };
  $("findStudentReport").onclick=find;$("studentIdSearch").onkeydown=e=>{if(e.key==="Enter")find();};
 }
 renderReport(u);if(u.role==="teacher")$("teacherEditor").classList.remove("hidden");
}
function renderReport(u){let s=selectedStudent(u);if(!s){$("reportStudentName").textContent="No student record is available.";return}window.currentReportStudentId=s.id;$("reportStudentName").textContent=`${s.name} • University ID: ${s.id}`;$("reportProfile").innerHTML=profileHTML(s);$("reportRows").innerHTML=(s.subjects||[]).map((x,i)=>{let total=Number(x.internal||0)+Number(x.external||0);return `<tr><td>${esc(x.name)}</td><td>${x.internal}/30</td><td>${x.external}/70</td><td>${total}/100</td><td>${grade(total)}</td></tr>`}).join("")||'<tr><td colspan="5">No subject marks have been entered yet.</td></tr>';$("averageValue").textContent=studentAverage(s)+"%";$("overallGrade").textContent=grade(Number(studentAverage(s)));$("remarksValue").textContent=s.remarks||"No remarks yet.";if(u.role==="teacher"){$("attendanceInput").value=s.attendance||0;$("cgpaInput").value=s.cgpa||0;$("remarksInput").value=s.remarks||""}}
function reportPageInitButtons(){let u=getUser();
$("removeInternal").onclick=()=>removeComponentMark("internal");
$("removeExternal").onclick=()=>removeComponentMark("external");
$("addSubject").onclick=()=>{let name=$("subjectName").value.trim();if(!name)return alert("Enter a subject name.");let s=readDB().students.find(x=>x.id===window.currentReportStudentId);if(s.subjects.some(x=>x.name.toLowerCase()===name.toLowerCase()))return alert("Subject already exists. Use Add / update marks.");s.subjects.push({name,internal:0,external:0});persistStudent(s);renderReport(u)};$("saveSubject").onclick=()=>{let name=$("subjectName").value.trim(),internal=Number($("internalMarks").value),external=Number($("externalMarks").value);if(!name||$("internalMarks").value===""||$("externalMarks").value==="")return alert("Enter subject, internal and external marks.");if(internal<0||internal>30||external<0||external>70)return alert("Internals must be 0–30 and externals 0–70.");let s=readDB().students.find(x=>x.id===window.currentReportStudentId),x=s.subjects.find(x=>x.name.toLowerCase()===name.toLowerCase());if(x){x.internal=internal;x.external=external}else s.subjects.push({name,internal,external});persistStudent(s);renderReport(u)};$("removeSubject").onclick=()=>{let name=$("subjectName").value.trim(),s=readDB().students.find(x=>x.id===window.currentReportStudentId);if(!name)return alert("Enter the subject name to remove.");s.subjects=s.subjects.filter(x=>x.name.toLowerCase()!==name.toLowerCase());persistStudent(s);renderReport(u)};$("saveReport").onclick=()=>{let attendance=Number($("attendanceInput").value),cgpa=Number($("cgpaInput").value);if(attendance<0||attendance>100||cgpa<0||cgpa>10)return alert("Attendance must be 0–100 and CGPA 0–10.");let s=readDB().students.find(x=>x.id===window.currentReportStudentId);s.attendance=attendance;s.cgpa=cgpa;s.remarks=$("remarksInput").value.trim();persistStudent(s);renderReport(u);alert("Report updated successfully.")}}
function persistStudent(s){let d=readDB(),i=d.students.findIndex(x=>x.id===s.id);d.students[i]=s;writeDB(d)}
function analyticsPage(u){
 let d=readDB(),wrap=$("analyticsPickerWrap"),picker=$("analyticsPicker");
 if(u.role==="admin"||u.role==="teacher"){
  wrap.classList.remove("hidden");picker.innerHTML=d.students.map(s=>`<option value="${esc(s.id)}">${esc(s.id)} — ${esc(s.name)}</option>`).join("");
  let q=new URLSearchParams(location.search).get("student");if(q){picker.value=q;$("analyticsStudentIdSearch").value=q;}
  picker.onchange=()=>{let id=picker.value;$("analyticsStudentIdSearch").value=id;history.replaceState(null,"","analytics.html?student="+encodeURIComponent(id));$("analyticsLookupMessage").textContent="";renderAnalytics(u,id);};
  const find=()=>{let id=$("analyticsStudentIdSearch").value.trim(),student=readDB().students.find(s=>s.id===id);
   if(!id){$("analyticsLookupMessage").style.color="#dc2626";$("analyticsLookupMessage").textContent="Please enter a university ID.";return;}
   if(!student){$("analyticsLookupMessage").style.color="#dc2626";$("analyticsLookupMessage").textContent="No student found with this university ID.";return;}
   picker.value=id;history.replaceState(null,"","analytics.html?student="+encodeURIComponent(id));$("analyticsLookupMessage").style.color="#059669";$("analyticsLookupMessage").textContent="Student analytics opened.";renderAnalytics(u,id);
  };
  $("findAnalyticsStudent").onclick=find;$("analyticsStudentIdSearch").onkeydown=e=>{if(e.key==="Enter")find();};
 }
 renderAnalytics(u,selectedStudent(u)?.id||picker.value);
}
function renderAnalytics(u,id){let d=readDB(),s=d.students.find(x=>x.id===id&&canSeeStudent(u,x));if(!s){$("analyticsSubtitle").textContent="No student report available.";return}let avg=Number(studentAverage(s));$("analyticsSubtitle").textContent=`${s.name} • University ID: ${s.id}`;$("avgStat").textContent=avg.toFixed(1)+"%";$("attendanceStat").textContent=(s.attendance||0)+"%";$("gradeStat").textContent=grade(avg);$("cgpaStat").textContent=Number(s.cgpa||0).toFixed(2);$("subjectBars").innerHTML=(s.subjects||[]).map(x=>{let t=Number(x.internal||0)+Number(x.external||0);return `<div class="bar-line"><b>${esc(x.name)}</b><div class="bar-track"><div class="bar-fill" style="width:${t}%"></div></div><strong>${t}%</strong></div>`}).join("")||"No subject marks available.";let best=(s.subjects||[]).slice().sort((a,b)=>(b.internal+b.external)-(a.internal+a.external))[0];$("analyticsText").textContent=`Average marks: ${avg.toFixed(1)}%. Attendance: ${s.attendance||0}%. CGPA: ${s.cgpa||0}. ${best?`Highest subject: ${best.name} (${Number(best.internal)+Number(best.external)}%).`:"No subject marks have been entered yet."}`}

function removeComponentMark(component){
 let s=readDB().students.find(x=>x.id===window.currentReportStudentId);
 let name=$("subjectName").value.trim();
 if(!name)return alert("Enter the subject name.");
 let subject=s.subjects.find(x=>x.name.toLowerCase()===name.toLowerCase());
 if(!subject)return alert("Subject not found.");
 subject[component]=0;
 persistStudent(s);renderReport(getUser());
}
